cy.pageIsLoaded();
const curvasFaltantes = [];
cy.document().then(doc => {
  curvas.forEach(curva => {
    // Buscar manualmente en el DOM
    const elementos = Array.from(doc.querySelectorAll('a'));
    const match = elementos.find(el => el.textContent.trim() === curva);
    if (match) {
      cy.wrap(match).should('be.visible');
    } else {
      cy.log(`No se encontró la curva: "${curva}"`);
      curvasFaltantes.push(curva);
    }
  });
});
cy.then(() => {
  if (curvasFaltantes.length > 0) {
    throw new Error(`Las siguientes curvas NO se encontraron:\n- ${curvasFaltantes.join('\n- ')}`);
  } else {
    cy.log('Todas las curvas esperadas fueron encontradas correctamente.');
  }
});

